        std::perror("_popen");
        return 1;
    }
    char buffer[256];
    // Читаем несколько сообщений
    for (int i = 0; i < 5; ++i) {
        if (fgets(buffer, sizeof(buffer), p))
            std::printf("parent: %s", buffer);
