The test:
```cpp
class BrokenPipeBuf : public std::streambuf {
  public:
    int_type overflow(int_type c) override {
        if (!std::char_traits<char>::eq_int_type(c, std::char_traits<char>::eof()))
            data_ += std::char_traits<char>::to_char_type(c);
        return std::char_traits<char>::not_eof(c);
    }
    int sync() override { return -1; }
    std::string data() const { return data_; }
  private:
    std::string data_;
};
```
Hmm — `std::char_traits<char>::eq_int_type`, `to_char_type`, `not_eof`, `eof` — these are the correct trait functions. Alternatively simpler:
```cpp
class BrokenPipeBuf : public std::streambuf {
  public:
    int_type overflow(int_type c) override {
        if (c != traits_type::eof())
            data_ += static_cast<char>(c);
        return traits_type::not_eof(c);
    }
    int sync() override { return -1; }
  private:
    std::string data_;
};
```
`traits_type` is a protected typedef in streambuf — accessible in the derived class. `traits_type::eof()` returns int_type; comparing int_type != int_type fine. `static_cast<char>(c)` — int_type is typically int; cast to char works for non-eof. Good.

